'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
// Ursprüngliche Adresse merken, bevor die Navigation den Hash ersetzt (für den Prüfstand).
const initialAppHash=location.hash;
// Zentraler Zugriff auf localStorage. read: Wert, null (leer) oder undefined (Lesen fehlgeschlagen).
// write/remove geben true bei Erfolg zurück. Fehler werden für die Fehlersuche protokolliert.
const appStorage={
 read(key){try{return JSON.parse(localStorage.getItem(key)||'null');}catch(error){console.warn('Gespeicherte Daten nicht lesbar:',key,error);return undefined;}},
 write(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch(error){console.warn('Speichern nicht möglich:',key,error);return false;}},
 remove(key){try{localStorage.removeItem(key);return true;}catch(error){console.warn('Entfernen nicht möglich:',key,error);return false;}}
};
const notes=[{id:'w',name:'Ganze Note',units:16},{id:'h',name:'Halbe Note',units:8},{id:'q',name:'Viertelnote',units:4},{id:'e',name:'Achtelnote',units:2},{id:'s',name:'Sechzehntelnote',units:1}];
const rests=notes.map(n=>({...n,id:n.id+'r',name:n.name.replace('Note','Pause').replace('note','pause'),rest:true}));
function sentenceName(name){return name.replace(/^(Ganze|Halbe|Punktierte)\b/,word=>word.toLowerCase());}
const dotted=notes.slice(0,4).map(n=>({...n,id:n.id+'d',name:'Punktierte '+sentenceName(n.name),units:n.units*1.5,dot:true}));
const dottedRests=rests.slice(0,4).map(n=>({...n,id:n.id+'d',name:'Punktierte '+sentenceName(n.name),units:n.units*1.5,dot:true}));
const all=[...notes,...rests,...dotted,...dottedRests,{id:'barrest',name:'Ganztaktpause',rest:true,units:16}];
const get=id=>all.find(n=>n.id===id), val=(id,m=4)=>id==='barrest'?m*4:get(id).units;
const fmt=x=>({0:'0',0.25:'¼',0.5:'½',0.75:'¾',1.5:'1½',2.5:'2½',3.5:'3½',4.5:'4½'}[x]||String(x).replace('.',','));
const duration=(id,m=4)=>fmt(val(id,m)/4)+' '+(val(id,m)<=4?'Schlag':'Schläge');
function symbol(id,{staff=true,label=true,beamed=false}={}){const n=get(id),base=id[0];let ink='';
 if(n.rest){if(base==='w'||id==='barrest')ink='<rect x="35" y="35" width="25" height="8"/>';else if(base==='h')ink='<rect x="35" y="42" width="25" height="8"/>';else if(base==='q')ink='<path d="M47 24 L57 38 L48 49 L57 62 Q38 54 42 68 L49 76 Q32 65 41 57 L48 56 L39 43 L49 33 Z"/>';else{ink='<path d="M57 31L43 77" fill="none" stroke="currentColor" stroke-width="3"/><path d="M56 34Q49 46 40 42Q31 35 38 31Q45 28 47 36Q51 38 56 34"/>';if(base==='s'&&!beamed)ink+='<path d="M51 50Q44 62 35 58Q26 51 33 47Q40 44 42 52Q46 54 51 50"/>';}}
 else{ink=`<ellipse cx="42" cy="65" rx="12" ry="8" transform="rotate(-18 42 65)" fill="${base==='w'||base==='h'?'var(--panel2)':'currentColor'}" stroke="currentColor" stroke-width="${base==='w'?3:2}"/>`;if(base!=='w')ink+='<path d="M53 64V20" stroke="currentColor" stroke-width="3"/>';if((base==='e'||base==='s')&&!beamed)ink+='<path d="M53 20Q78 29 65 48Q70 33 53 29Z"/>';if(base==='s'&&!beamed)ink+='<path d="M53 32Q78 41 65 60Q70 45 53 41Z"/>';}
 // Der Verlängerungspunkt steht im Zwischenraum, nicht auf einer Notenlinie.
 if(n.dot)ink+=`<circle cx="75" cy="${n.rest?42.5:57.5}" r="3.5"/>`;
 return `<svg viewBox="0 0 100 100" ${label?`role="img" aria-label="${n.name}"`:'aria-hidden="true"'} style="color:inherit">${staff?[20,35,50,65,80].map(y=>`<path d="M5 ${y}H95" stroke="currentColor" stroke-width=".7" opacity=".4"/>`).join(''):''}<g fill="currentColor">${ink}</g></svg>`;
}
function seq(ids,m=4,cls=''){return `<div class="sequence ${cls}">${ids.map((id,i)=>`<div class="noteTile" data-index="${i}">${symbol(id)}<span>${get(id).name}</span><small>${duration(id,m)}</small></div>`).join('')}</div>`;}
const tip=(s)=>`<div class="tip"><strong>Merksatz</strong><br>${s}</div>`;
const beats=m=>`<div class="beatRow" aria-label="Zählzeiten">${Array.from({length:m},(_,i)=>`<span class="beat" data-beat="${i}">${i+1}</span>`).join('')}</div>`;
let editIndex=-1,view='learn',lesson=0,meter=4,build=[],fixed=[],task=null,advanced=false,quiz=null,audioURL=null,audioFrame=null,playToken=0;
const chapters=['Puls & Notenwerte','Pausen & Stille','Noten beschriften','Takte & Taktstriche','Rhythmuswörter','Punktierte Noten'];
function clearMarks(){$$('.playing,.active,.listening').forEach(e=>e.classList.remove('playing','active','listening'));}
function stop(){if(typeof tapPhase!=='undefined'&&tapPhase==='recording'){tapPhase='idle';const status=$('#tapStatus');if(status)status.textContent='Runde unterbrochen. Starte das Nachklopfen erneut.';}playToken++;if(audioFrame!==null){cancelAnimationFrame(audioFrame);audioFrame=null;}const player=$('#rhythmAudio');player.onplaying=null;player.onended=null;player.onerror=null;player.pause();try{player.currentTime=0;}catch{/* Ohne geladene Audiodaten nicht zurücksetzbar – unkritisch. */}clearMarks();$('#soundStatus').textContent='Gestoppt. Bereit zum Hören.';}
function makeRhythmWav(events,m=4,opts={}){const rate=22050,seconds=60/Number($('#tempo').value),total=events.reduce((a,e)=>a+e.u,0),length=Math.ceil(total/4*seconds*rate),samples=new Float32Array(length);let offset=0;
 function add(time,dur,freq,volume){const from=Math.round(time*rate),count=Math.round(dur*rate);for(let i=0;i<count&&from+i<length;i++){const t=i/rate,envelope=Math.min(1,t/.012,Math.max(0,(dur-t)/.04));samples[from+i]+=volume*envelope*(Math.sin(2*Math.PI*freq*t)+.15*Math.sin(4*Math.PI*freq*t));}}
 events.forEach(e=>{if(!e.rest){add(offset/4*seconds,e.click ? .055 : e.u/4*seconds*(opts.fullDuration?1:.94),e.freq||opts.freq||330,e.volume ?? (e.click ? .13 : .34));if(e.extra)add(offset/4*seconds,e.u/4*seconds*(opts.fullDuration?1:.94),e.extra,.18);}offset+=e.u;});if($('#metro').checked&&!opts.silentClick)for(let b=0;b<Math.ceil(total/4);b++)add(b*seconds,.04,b%m===0?1000:700,.12);
 const buffer=new ArrayBuffer(44+length*2),data=new DataView(buffer),ascii=(at,text)=>{for(let i=0;i<text.length;i++)data.setUint8(at+i,text.charCodeAt(i));};ascii(0,'RIFF');data.setUint32(4,36+length*2,true);ascii(8,'WAVE');ascii(12,'fmt ');data.setUint32(16,16,true);data.setUint16(20,1,true);data.setUint16(22,1,true);data.setUint32(24,rate,true);data.setUint32(28,rate*2,true);data.setUint16(32,2,true);data.setUint16(34,16,true);ascii(36,'data');data.setUint32(40,length*2,true);for(let i=0;i<length;i++)data.setInt16(44+i*2,Math.round(Math.max(-1,Math.min(1,samples[i]))*32767),true);return {buffer,seconds,total};}
function play(ids,m=4,opts={}){stop();const token=playToken,player=$('#rhythmAudio'),scope=opts.hideEvents?null:(opts.target||((quiz?.mode==='hear'&&view==='practice')?null:$('#main .sequence')));try{const musicalEvents=ids.map(id=>typeof id==='string'?{id,u:val(id,m),rest:get(id).rest}:id),leadCount=opts.leadIn?m:0,events=[...Array.from({length:leadCount},()=>({u:4,click:true,freq:880})),...musicalEvents],wav=makeRhythmWav(events,m,opts);if(audioURL)URL.revokeObjectURL(audioURL);audioURL=URL.createObjectURL(new Blob([wav.buffer],{type:'audio/wav'}));player.src=audioURL;player.muted=false;player.volume=1;let active=-1;
 const update=()=>{if(token!==playToken)return;const units=player.currentTime/wav.seconds*4;let sum=0,index=events.findIndex(e=>{sum+=e.u;return units<sum;});if(index!==active){active=index;clearMarks();if(scope)[...scope.querySelectorAll('[data-index]')].forEach(el=>el.classList.toggle('playing',Number(el.dataset.index)===index-leadCount));}const beat=Math.floor(units/4)%m;$$('[data-beat]').forEach(el=>el.classList.toggle('active',Number(el.dataset.beat)===beat));opts.onProgress?.({units:units-leadCount*4,index:index-leadCount});$('#soundStatus').textContent=index<0?'Fertig.':index<leadCount?`Einzählen: ${index+1} von ${leadCount}`:opts.hideEvents?'Rhythmus hören – zähle mit.':index>=0?(events[index].rest?'Pause – still weiterzählen.':`Klang ${index-leadCount+1} von ${musicalEvents.length}`):'Fertig.';if(!player.paused&&!player.ended)audioFrame=requestAnimationFrame(update);};
 player.onplaying=()=>{if(token!==playToken)return;if(audioFrame!==null)cancelAnimationFrame(audioFrame);update();};player.onended=()=>{if(token!==playToken)return;if(audioFrame!==null){cancelAnimationFrame(audioFrame);audioFrame=null;}clearMarks();$('#soundStatus').textContent='Fertig. Du kannst noch einmal hören.';opts.onComplete?.();};player.onerror=()=>{if(typeof showAudioControls==='function')showAudioControls(true);if(token===playToken)$('#soundStatus').textContent='Klang konnte nicht geladen werden. Bitte die Seite neu öffnen.';};$('#soundStatus').textContent='Klang wird vorbereitet …';const result=player.play();if(result?.catch)return result.catch(e=>{if(token!==playToken)return;if(typeof showAudioControls==='function')showAudioControls(true);$('#soundStatus').textContent=e.name==='NotAllowedError'?'Bitte die Wiedergabetaste im Audioplayer antippen.':'Klang startet nicht. Bitte die Wiedergabetaste im Audioplayer nutzen oder die Seite in Safari öffnen.';});}catch(e){if(typeof showAudioControls==='function')showAudioControls(true);$('#soundStatus').textContent='Klang konnte nicht vorbereitet werden. Bitte Seite neu öffnen.';}}

// Erweiterungspunkte der Navigation: Guards dürfen die Zielansicht umschreiben,
// Before-Hooks laufen vor dem Wechsel (alte, neue Ansicht), After-Hooks nach dem Rendern.
const viewGuards=[],beforeViewHooks=[],afterViewHooks=[];
function onViewGuard(guard){viewGuards.push(guard);}
function onBeforeViewChange(hook){beforeViewHooks.push(hook);}
function onAfterViewChange(hook){afterViewHooks.push(hook);}
function setView(v){for(const guard of viewGuards)v=guard(v);const previous=view;for(const hook of beforeViewHooks)hook(previous,v);stop();if(view==='detective'&&detectRound?.answered){detectNumber++;newDetectiveRound();}view=v;$$('nav button').forEach(b=>b.classList.toggle('selected',b.dataset.view===v));render();for(const hook of afterViewHooks)hook(v,previous);}
// Zentrale Zuordnung der Ansichten zu ihren Renderern. Module melden Ansichten mit registerView an;
// onAfterRender registriert Arbeiten, die nach jedem Rendern laufen (die Hooks sichern sich selbst ab).
// Thunks sorgen dafür, dass später ersetzte Renderer (z. B. durch mobileWrap) wirksam bleiben.
const viewRenderers={};
function registerView(name,renderer){viewRenderers[name]=renderer;}
const afterRenderHooks=[];
function onAfterRender(hook){afterRenderHooks.push(hook);}
function render(){(viewRenderers[view]||viewRenderers.rhythm)();for(const hook of afterRenderHooks)hook();}
registerView('learn',()=>renderLearn());registerView('practice',()=>renderPractice());registerView('builder',()=>renderBuilder());registerView('detective',()=>renderDetective());registerView('tests',()=>renderTests());registerView('tap',()=>renderTap());registerView('device',()=>renderDeviceCheck());registerView('dotted',()=>renderDotted());registerView('rhythm',()=>renderRhythm());
function valueCards(list){return `<div class="grid values">${list.map(n=>`<div class="value">${symbol(n.id)}<strong>${n.name}</strong><div class="length">${duration(n.id)}</div>${n.rest?'<span class="legend">Stille – innerlich zählen</span>':`<button class="subtle" data-hear="${n.id}" aria-label="${n.name} anhören">Anhören</button>`}</div>`).join('')}</div>`;}
function renderLearn(){let body='';if(lesson===0)body=`<h2>Der Puls ist dein gleichmäßiger Grundschlag.</h2><p>Tippe oder klatsche gleichmäßig mit: 1, 2, 3, 4. Der Rhythmus verteilt lange und kurze Töne auf diesen Puls. Hier zählt eine Viertelnote als ein Schlag.</p>${beats(4)}<button class="primary" id="pulse">Puls hören & mitklatschen</button><h3 class="spaced">Von lang zu kurz</h3>${valueCards(notes)}${tip('1 Ganze = 2 Halbe = 4 Viertel = 8 Achtel = 16 Sechzehntel. Jede Stufe halbiert die Dauer.')}<p>Die <strong>Form</strong> der Note zeigt ihre Dauer. Das Tempo bestimmt, wie lang ein Schlag in Sekunden dauert. Bei 60 Schlägen pro Minute dauert ein Schlag eine Sekunde.</p>`;
 if(lesson===1)body=`<h2>Eine Pause ist geplante Stille.</h2><p>Während deiner Pause singst oder spielst du nicht. Du zählst innerlich weiter und setzt danach pünktlich ein. Eine Pause kann genauso lang sein wie eine Note.</p>${valueCards(rests)}${tip('Noten klingen. Pausen schweigen. Beide brauchen Zeit.')}<div class="two"><div><h3>Eine Stimme schweigt</h3><p>Du hast eine Pause, andere dürfen weiterspielen.</p>${staffScore(['q','qr','q','qr'],4)}<button id="restDemo">Ton – Stille – Ton – Stille</button></div><div><h3>Generalpause · G.P.</h3><p>Alle Stimmen schweigen gleichzeitig. „Generalschweigen“ beschreibt das; der Fachbegriff lautet <strong>Generalpause</strong>. Ihre Dauer wird durch die Notation festgelegt.</p>${staffScore(['q','q','hr'],4)}<button id="gpDemo">Gemeinsam spielen, dann schweigen</button><p class="legend spaced">Im Beispiel verstummen auch die Zählklicks. Die Zählkreise laufen weiter.</p></div></div>${beats(4)}<h3 class="spaced">Achtung: Ganztaktpause</h3><p>Das Zeichen der ganzen Pause kann einen <strong>vollständig stillen Takt</strong> bezeichnen. Dann dauert es so lang wie der Takt: im 3/4-Takt drei Schläge, im 4/4-Takt vier. In der Werkstatt heißt diese Auswahl ausdrücklich „Ganztaktpause“.</p>`;
 if(lesson===2)body=`<h2>So ist eine Note aufgebaut.</h2><p>Tippe auf die Bestandteile, um sie kennenzulernen. Nicht jede Note hat alle Teile!</p><svg class="anatomy" viewBox="0 0 500 230" role="img" aria-label="Sechzehntelnote mit Notenkopf, Notenhals und zwei Fähnchen"><ellipse cx="140" cy="170" rx="30" ry="19" transform="rotate(-20 140 170)" fill="currentColor"/><path d="M166 166V35" stroke="currentColor" stroke-width="7"/><path d="M166 35Q230 65 205 116Q219 80 166 62Z M166 67Q230 97 205 148Q219 112 166 94Z" fill="currentColor"/><path d="M111 178L40 207M169 125H300M210 72L330 42" stroke="var(--mint)" stroke-width="2"/><text x="10" y="221" fill="var(--mint)" font-size="20">1</text><text x="310" y="132" fill="var(--mint)" font-size="20">2</text><text x="340" y="45" fill="var(--mint)" font-size="20">3</text></svg><div class="grid"><button data-part="0">1 · Notenkopf</button><button data-part="1">2 · Notenhals</button><button data-part="2">3 · Fähnchen</button></div><div id="partInfo" class="feedback" role="status">Der Notenkopf kann leer oder ausgefüllt sein.</div><h3 class="spaced">Balken verbinden kurze Noten</h3>${groupSVG(['e','e'])}<p>Zwei Achtel können mit <strong>einem Balken</strong> verbunden sein. Sechzehntel bekommen <strong>zwei Balken</strong>. Der Balken ersetzt das Fähnchen; der Wert bleibt gleich.</p>${groupSVG(['s','s','s','s'])}${tip('Ganze: leerer Kopf, kein Hals. Halbe: leerer Kopf + Hals. Viertel: ausgefüllter Kopf + Hals. Achtel: ein Fähnchen. Sechzehntel: zwei Fähnchen.')}<h3>Pausen haben eigene Zeichen</h3><p>Eine Pause hat keinen Notenkopf und keinen Notenhals. Die ganze Pause <strong>hängt unter einer Linie</strong>, die halbe Pause <strong>sitzt auf einer Linie</strong>. Die Achtelpause hat ein Häkchen, die Sechzehntelpause zwei.</p><button class="primary" id="labelGo">Jetzt beschriften üben</button>`;
 if(lesson===3)body=`<h2>Ein Takt ordnet die Schläge.</h2><p>Ein Taktstrich trennt zwei Takte. Zwischen zwei Taktstrichen müssen Noten und Pausen zusammen genau den Wert der Taktart ergeben.</p><div class="two"><div class="value"><div class="meter"><span>3</span><span>4</span></div><strong>3 Viertelschläge pro Takt</strong><p>Oben: Wie viele? Unten: Welcher Notenwert zählt? Die 4 steht für die Viertelnote.</p>${beats(3)}<button data-meterdemo="3">3/4 hören</button></div><div class="value"><div class="meter"><span>4</span><span>4</span></div><strong>4 Viertelschläge pro Takt</strong><p>Der erste Schlag ist betont. Im 4/4 ist der dritte oft etwas betont: stark – leicht – mittel – leicht.</p>${beats(4)}<button data-meterdemo="4">4/4 hören</button></div></div>${tip('Zähle den Wert, nicht die Anzahl der Zeichen! Eine halbe Note + eine Viertelnote füllen einen 3/4-Takt.')}<h3>Taktstrich, Doppelstrich, Schlussstrich</h3><svg class="barlines" viewBox="0 0 500 130" role="img" aria-label="Einfacher Taktstrich, Doppelstrich und Schlussstrich">${[20,35,50,65,80].map(y=>`<path d="M10 ${y}H490" stroke="currentColor" opacity=".3"/>`).join('')}<path d="M85 20V80 M240 20V80 M249 20V80 M395 20V80" stroke="currentColor" stroke-width="2"/><path d="M407 20V80" stroke="currentColor" stroke-width="6"/><g fill="currentColor" font-size="16"><text x="45" y="115">Taktstrich</text><text x="205" y="115">Doppelstrich</text><text x="360" y="115">Schlussstrich</text></g></svg><p>Ein einfacher Strich trennt Takte. Zwei dünne Striche markieren einen Abschnitt. Ein dünner und ein dicker Strich markieren das Ende.</p><button class="primary" id="builderGo">Einen Takt vervollständigen</button>`;
 if(lesson===4)body=`<h2>Wörter machen Rhythmus sprechbar.</h2><p>Sprich die Silben gleichmäßig und klatsche bei jeder Silbe. Jedes Wort füllt einen Viertelschlag.</p><div class="grid">${wordCard('Brot','Brot',['q'])}${wordCard('Käse','Kä – se',['e','e'])}${wordCard('Schokolade','Scho – ko – la – de',['s','s','s','s'])}${wordCard('Ananas','A – na – nas',['s','s','e'])}</div>${tip('Ein Brot, zwei Käse-Silben, vier Schokolade-Silben oder drei Ananas-Silben dauern jeweils einen Schlag. Ananas: kurz – kurz – länger (¼ + ¼ + ½).')}<button class="primary" id="rhythmGo">Worttakte zusammenstellen</button><h3 class="spaced">Der verbotene Rhythmus</h3><p>Merke dir einen bestimmten Takt. Wenn genau dieser Rhythmus wiederkommt, schweigst du. Andere Rhythmen darfst du nachklatschen. Die Stille ist Teil der Spielregel – der gemerkte Takt ist musikalisch korrekt.</p><button id="forbiddenGo">Spiel ausprobieren</button>`;
 if(lesson===5)body=`<button id="dotTopicOpen" class="primary">Eigenes Thema „Punktierte Noten“ öffnen</button><h2 class="spaced">Der Punkt verlängert um die Hälfte.</h2><p>Ein Punkt <strong>rechts neben</strong> der Note fügt die Hälfte ihres ursprünglichen Wertes hinzu. Er verdoppelt die Note nicht. Ein Punkt über oder unter einer Note kann etwas anderes bedeuten.</p><div class="grid">${dotted.slice(1).map(n=>`<div class="value">${symbol(n.id)}<strong>${n.name}</strong><div class="length">${duration(n.id)}</div><p>${fmt(n.units/6)} + ${fmt(n.units/12)} = ${fmt(n.units/4)} Schläge</p><button data-hear="${n.id}">Anhören</button></div>`).join('')}</div>${tip('Wert + halber Wert = punktierter Wert. Halbe: 2 + 1 = 3. Viertel: 1 + ½ = 1½. Achtel: ½ + ¼ = ¾.')}<h3>Lang – kurz: punktierte Viertel + Achtel</h3>${seq(['qd','e'])}<button id="dotDemo">Lang – kurz anhören</button>${beats(4)}<p>Zusammen dauern diese beiden Noten zwei Schläge. Eine punktierte Halbe füllt genau einen 3/4-Takt.</p><h3>Auch Pausen können punktiert sein</h3><p>Eine punktierte Viertelpause bedeutet 1½ Schläge Stille. Für Pausen gilt dieselbe Regel. In geschriebenen Takten werden Pausen oft so aufgeteilt, dass die Zählzeiten gut sichtbar bleiben.</p>${staffScore(['q','qrd','e','q'],4)}<button id="dottedRestDemo">Takt mit punktierter Pause hören</button>`;
 $('#main').innerHTML=`<div class="layout"><aside class="lessonNav" aria-label="Lernkapitel">${chapters.map((c,i)=>`<button data-lesson="${i}" class="${lesson===i?'selected':''}"><span>${i+1}</span>${c}</button>`).join('')}</aside><section class="card"><div class="eyebrow">Lernen · ${lesson+1} von 6</div>${guideSteps[lesson]===0?`<button id="guideStartTop" class="subtle">Zum vorgemachten Beispiel</button><div class="spaced">${body}</div>`:''}${guideCard(lesson)}${guideSteps[lesson]>0?`<details class="spaced"><summary>Erklärung nachlesen</summary>${body}</details>`:''}<div class="row spaced"><button id="prevLesson" ${lesson===0?'disabled':''}>Vorheriges Kapitel</button><button class="primary" id="nextLesson">${lesson===5?'Jetzt üben':'Nächstes Kapitel'}</button></div></section></div>`;
 $$('[data-lesson]').forEach(b=>b.onclick=()=>{stop();lesson=+b.dataset.lesson;renderLearn();});$('#prevLesson').onclick=()=>{lesson--;stop();renderLearn();};$('#nextLesson').onclick=()=>{if(lesson===5){quiz=null;setView('practice');}else{lesson++;stop();renderLearn();}};
 on('dotTopicOpen',()=>{dotTab='learn';setView('dotted');});bindGuide();bindHear();on('pulse',()=>play(['q','q','q','q','q','q','q','q']));on('restDemo',()=>play(['q','qr','q','qr'],4,{silentClick:true,target:$('#restDemo').parentElement}));on('gpDemo',()=>play([{u:4,extra:660},{u:4,extra:660},{u:8,rest:true}],4,{silentClick:true,freq:440,target:$('#gpDemo').parentElement}));on('dotDemo',()=>play(['qd','e','qd','e']));on('dottedRestDemo',()=>play(['q','qrd','e','q'],4,{silentClick:true,target:$('#dottedRestDemo').previousElementSibling}));on('forbiddenGo',()=>{detectMode='taboo';newDetectiveRound(true);setView('detective');});on('builderGo',()=>{newTask();setView('builder');});on('rhythmGo',()=>setView('rhythm'));on('labelGo',()=>{quiz={mode:'label'};setView('practice');});$$('[data-part]').forEach(b=>b.onclick=()=>{$('#partInfo').textContent=['Notenkopf: leer bei Ganzen und Halben, ausgefüllt bei Vierteln und kürzeren Noten.','Notenhals: der Strich am Kopf. Die ganze Note hat keinen Hals.','Fähnchen: ein Fähnchen bei Achteln, zwei bei Sechzehnteln. Ein Balken kann die Fähnchen ersetzen.'][+b.dataset.part];});$$('[data-meterdemo]').forEach(b=>b.onclick=()=>play(Array(+b.dataset.meterdemo*2).fill('q'),+b.dataset.meterdemo));}
function focusLearningArea(){const main=$('#main');if(!main)return;main.focus({preventScroll:true});if(typeof main.scrollIntoView==='function')main.scrollIntoView({block:'start',behavior:'auto'});}
function on(id,fn){const e=$('#'+id);if(e)e.onclick=fn;}
function bindHear(){$$('[data-hear]').forEach(b=>b.onclick=()=>play(b.dataset.hear.split(','),4,{target:b.closest('.value')}));}
function groupSVG(ids){const n=ids.length,w=Math.max(150,n*62+30);let stems=ids.map((id,i)=>`<g data-index="${i}"><ellipse cx="${25+i*62}" cy="80" rx="11" ry="7" transform="rotate(-18 ${25+i*62} 80)" fill="currentColor"/><path d="M${35+i*62} 80V25" stroke="currentColor" stroke-width="3"/></g>`).join('');let beams=n>1?`<path d="M35 25H${35+(n-1)*62}" stroke="currentColor" stroke-width="7"/>`:'';ids.forEach((id,i)=>{if(id==='s'&&(i===0||ids[i-1]!=='s')){let end=i;while(ids[end+1]==='s')end++;const x=35+i*62,y=35+end*62;beams+=`<path d="M${x} 38H${end===i?x+18:y}" stroke="currentColor" stroke-width="7"/>`;}});return `<svg viewBox="0 0 ${w} 110" role="img" aria-label="${ids.map(id=>get(id).name).join(', ')}" style="width:${w}px;max-width:100%;height:110px;color:var(--ink)">${stems}${beams}</svg>`;}

function wordCard(name,syllables,ids){return `<article class="value wordCard"><div class="word">${name}</div>${groupSVG(ids)}<p>${syllables}<br><strong>${ids.length} ${ids.length===1?'Ton':'Töne'} · 1 Schlag</strong></p><button data-hear="${ids.join(',')}">Rhythmus hören</button></article>`;}
function makeQuestions(){let qs=[];[...notes,...rests,...dotted.slice(1),...dottedRests.slice(1)].forEach(n=>{qs.push({kind:'symbol',symbol:n.id,q:'Wie heißt dieses Zeichen?',answer:n.name,options:[],lesson:n.dot?5:n.rest?1:0,hint:n.rest?'Vergleiche Hängen, Sitzen und die Anzahl der Häkchen.':'Prüfe Kopf, Hals, Fähnchen und Punkt.',explain:`Das ist eine ${sentenceName(n.name)}. Sie dauert ${duration(n.id)}.`});qs.push({q:`Wie lange dauert eine ${sentenceName(n.name)} in 3/4 oder 4/4?`,answer:duration(n.id),options:shuffle([...new Set([duration(n.id),'¼ Schlag','½ Schlag','1 Schlag','2 Schläge','3 Schläge','4 Schläge','1½ Schläge','¾ Schlag'])].filter(x=>x!==duration(n.id))).slice(0,3).concat(duration(n.id)),lesson:n.dot?5:n.rest?1:0,hint:n.dot?'Nimm den Grundwert und addiere seine Hälfte.':'Eine Viertel zählt einen Schlag; nach unten halbierst du.',explain:`${n.name}: ${duration(n.id)}.`});});
 const extra=[['Was tust du während einer Pause?','Still sein und innerlich weiterzählen',['Das Tempo anhalten','Sofort neu anfangen','Eine lange Note spielen'],1,'Auch Stille hat eine Dauer.'],['Was bedeutet Generalpause?','Alle Stimmen schweigen gleichzeitig',['Nur du schweigst','Alle spielen gleichzeitig','Die Musik endet immer'],1,'„General“ meint hier alle Stimmen.'],['Wie lange ist eine Ganztaktpause im 3/4-Takt?','3 Schläge',['4 Schläge','2 Schläge','1 Schlag'],1,'Eine Ganztaktpause füllt den gesamten Takt.'],['Wie viele Viertelschläge passen in einen 4/4-Takt?','4',['3','8','2'],3,'Die obere Zahl nennt die Anzahl.'],['Wofür steht die untere 4 in 3/4?','Für den Notenwert Viertel',['Für vier Takte','Für vier Instrumente','Für vier Schläge'],3,'Die untere Zahl benennt den Wert der Zählzeit.'],['Was macht ein einfacher Taktstrich?','Er trennt zwei Takte',['Er verlängert eine Note','Er bedeutet eine Pause','Er ändert die Tonhöhe'],3,'Der Strich gliedert die Zeit.'],['Welches Muster passt zu Käse?','Zwei Achtel',['Zwei Viertel','Vier Sechzehntel','Eine halbe Note'],4,'Kä – se: zwei Silben innerhalb eines Viertelschlags.'],['Welches Muster passt zu Schokolade?','Vier Sechzehntel',['Vier Viertel','Zwei Achtel','Eine ganze Note'],4,'Scho – ko – la – de: vier gleichmäßige Silben in einem Schlag.'],['Welches Muster passt zu Ananas?','Zwei Sechzehntel und eine Achtel',['Drei Achtel','Drei Viertel','Vier Sechzehntel'],4,'A – na – nas: ¼ + ¼ + ½ = ein Schlag. Die letzte Silbe dauert länger.'],['Welches Muster passt zu Brot?','Eine Viertel',['Eine Achtel','Eine Halbe','Eine Ganze'],4,'Ein Brot ist ein Schlag.'],['Was macht ein Punkt rechts neben einer Note?','Er verlängert um die Hälfte des Grundwertes',['Er verdoppelt immer','Er macht die Note leiser','Er halbiert die Dauer'],5,'Grundwert + halber Grundwert.'],['Wie heißt der ausgefüllte ovale Teil einer Note?','Notenkopf',['Notenhals','Fähnchen','Taktstrich'],2,'Der Kopf sitzt am Ende des Halses.'],['Wie viele Balken haben verbundene Sechzehntel?','Zwei',['Einen','Drei','Keine'],2,'Die Balken ersetzen die zwei Fähnchen.']];extra.forEach(([q,a,o,l,h])=>qs.push({q,answer:a,options:shuffle([a,...o]),lesson:l,hint:h,explain:h}));
 [['q','e','e'],['qd','e'],['q','qr','q'],['e','e','e','e'],['s','s','s','s','q']].forEach(ids=>qs.push({kind:'hear',ids,q:'Höre zu. Welchen Rhythmus hörst du?',answer:ids.join(','),options:[],lesson:0,hint:'Höre auf die Anzahl der Tonanfänge und die stillen Stellen.',explain:`Die richtige Folge ist: ${ids.map(id=>get(id).name).join(' – ')}.`}));return qs;}
function shuffle(a){return [...a].sort(()=>Math.random()-.5);}
function startQuiz(mode){const pool=makeQuestions().filter(q=>mode==='mix'||mode==='hear'?mode==='mix'||q.kind==='hear':mode==='rest'?q.lesson===1:mode==='dot'?q.lesson===5:q.lesson===0||q.lesson===2||q.lesson===3||q.lesson===4);quiz={mode,questions:shuffle(pool).slice(0,10),index:0,score:0,answered:false,hinted:false,assistedCount:0,wrongQuestions:[]};renderPractice();}
function renderPractice(){if(!quiz){$('#main').innerHTML=`<div class="eyebrow">Erst verstehen, dann ausprobieren</div><h1>Deine Musikübungen</h1><p class="muted">Wähle einen Bereich. Tipps helfen dir vor der Antwort. Nach jedem Fehler kannst du die passende Erklärung öffnen.</p><div class="grid spaced">${[['mix','Gemischte Runde','10 Aufgaben · ca. 5 Min. Noten, Pausen, Takt und Punkt.'],['base','Noten & Takte','10 Aufgaben · ca. 5 Min. Zeichen erkennen und Werte vergleichen.'],['rest','Pausen & Stille','10 Aufgaben · ca. 5 Min. Pausen erkennen und Generalpause verstehen.'],['dot','Punktierte Noten','10 Aufgaben · ca. 5 Min. Werte, Taktlücken und Hörvergleich.'],['hear','Hördetektiv','10 Aufgaben · ca. 5 Min. Tonfolgen hören und passende Noten wählen.'],['label','Beschriften','Kurze Runde · ca. 3 Min. Bestandteile einer Note zuordnen.'],['detective','Rhythmusdetektiv','Aufgaben in mehreren Runden · ca. 5 Min. Taktfehler, Pausen und Taktstriche.']].map(([id,title,desc])=>`<article class="card"><h2>${title}</h2><p>${desc}</p><button class="primary" data-start="${id}">Übung starten</button></article>`).join('')}</div>`;$$('[data-start]').forEach(b=>b.onclick=()=>b.dataset.start==='dot'?(dotTab='calc',startDotRound(true),setView('dotted')):b.dataset.start==='detective'?setView('detective'):b.dataset.start==='label'?(quiz={mode:'label'},renderPractice()):startQuiz(b.dataset.start));return;}
 if(quiz.mode==='label'){renderLabels();return;}if(quiz.index>=quiz.questions.length){const mistakes=quiz.wrongQuestions;$('#main').innerHTML=`<section class="card"><div class="eyebrow">10 Aufgaben · ungefähr 5 Minuten</div><h1>${quiz.score} von ${quiz.questions.length} richtig</h1>${quiz.assistedCount?`<p>${quiz.assistedCount} Antworten mit Tipp geübt. Sie zählen nicht als selbstständiger Themenfortschritt.</p>`:''}<p>${quiz.score===quiz.questions.length&&!quiz.assistedCount?'Du erkennst die Rhythmen und Zeichen sicher. Probiere jetzt einen eigenen Takt.':'Übe schwierige Bereiche noch einmal. Fehler zeigen dir, was du als Nächstes lernen kannst.'}</p>${mistakes.length?`<section class="smartMistakes"><h2>Fragen zum Wiederholen</h2><ul>${mistakes.map(q=>`<li>${q.lesson===undefined?'':topicTitles[q.lesson]+': '}${escapeText(q.q)}</li>`).join('')}</ul><button class="primary" id="retryQuizMistakes">Diese ${mistakes.length} Fehler gezielt wiederholen</button></section>`:''}<button class="primary" id="again">Neue Runde · 10 Aufgaben · ca. 5 Min</button> <button id="menu">Andere Übung wählen</button> <button id="goBuild">Takte bauen</button></section>`;on('retryQuizMistakes',()=>startSmart('targeted',null,mistakes.map(q=>({...q,topic:q.lesson,why:q.explain}))));on('again',()=>startQuiz(quiz.mode));on('menu',()=>{quiz=null;renderPractice();});on('goBuild',()=>setView('builder'));return;}
 const q=quiz.questions[quiz.index];let opts=quiz.optionIndex===quiz.index?quiz.options:q.options;if(quiz.optionIndex!==quiz.index&&q.kind==='symbol')opts=shuffle([q.answer,...shuffle(all.filter(n=>n.id!=='barrest'&&n.name!==q.answer&&n.rest===get(q.symbol).rest)).slice(0,3).map(n=>n.name)]);if(quiz.optionIndex!==quiz.index&&q.kind==='hear')opts=shuffle([q.answer,...shuffle(['q,q,q','q,q','h,q','e,e,q','qd,e,q','q,qr','e,e,e,e','s,s,s,s,q'].filter(x=>x!==q.answer)).slice(0,3)]);quiz.options=opts;quiz.optionIndex=quiz.index;
 $('#main').innerHTML=`<section class="card"><div class="row"><span class="eyebrow">Aufgabe ${quiz.index+1} von ${quiz.questions.length} · ca. 5 Min insgesamt</span><span class="pill">${quiz.score} richtig</span></div><progress class="progress" max="${quiz.questions.length}" value="${quiz.index}"></progress><h1>${q.q}</h1>${q.symbol?`<div class="bigSymbol">${symbol(q.symbol,{label:false})}</div>`:''}${q.kind==='hear'?'<button class="primary" id="hearQuestion">Rhythmus anhören</button>'+beats(4):''}<div class="answerGrid">${opts.map((a,i)=>`<button data-answer="${i}">${q.kind==='hear'?seq(a.split(',')):a}</button>`).join('')}</div><button id="hint">Tipp anzeigen</button><div id="hintText" class="tip" hidden></div><div id="result" class="feedback" role="status"></div><div id="quizSupport"></div><div class="row"><button id="nextQuestion" class="primary" hidden>Nächste Frage</button><button id="relearn" hidden>Passende Erklärung</button><button id="backMenu">Übung wechseln</button></div></section>`;
 $('#hint').disabled=!!quiz.answered;if(quiz.hinted){$('#hintText').hidden=false;$('#hintText').textContent=q.hint+' Mit Tipp übst du mit Unterstützung; diese Antwort zählt nicht zum selbstständigen Fortschritt.';}on('hearQuestion',()=>play(q.ids));on('hint',()=>{if(quiz.answered)return;quiz.hinted=true;$('#hintText').hidden=false;$('#hintText').textContent=q.hint+' Mit Tipp zählt die Antwort als unterstütztes Üben.';});on('backMenu',()=>{stop();quiz=null;renderPractice();});$$('[data-answer]').forEach(b=>b.onclick=()=>{if(quiz.answered)return;quiz.answered=true;$('#hint').disabled=true;stop();const correct=opts[+b.dataset.answer]===q.answer;quiz.chosen=opts[+b.dataset.answer];if(!quiz.hinted)recordSkill(q.lesson,correct,q.q,q.q);else quiz.assistedCount=(quiz.assistedCount||0)+1;if(correct)quiz.score++;else quiz.wrongQuestions.push({...q});$('#result').className='feedback '+(correct?'good':'bad');$('#result').textContent=(quiz.hinted?'Mit Hilfe geübt. ':'')+(correct?'Richtig! ':'Noch nicht. ')+q.explain;$$('[data-answer]').forEach((b,i)=>{b.disabled=true;if(opts[i]===q.answer)b.classList.add('selected');});$('#nextQuestion').hidden=false;$('#relearn').hidden=correct;if(!correct)showSupport('quizSupport',q.lesson);});on('nextQuestion',()=>{quiz.index++;quiz.answered=false;quiz.hinted=false;stop();renderPractice();focusLearningArea();});on('relearn',()=>{lesson=q.lesson;setView('learn');});if(quiz.answered){const correct=quiz.chosen===q.answer;$('#result').className='feedback '+(correct?'good':'bad');$('#result').textContent=(quiz.hinted?'Mit Hilfe geübt. ':'')+(correct?'Richtig! ':`Deine Antwort: ${quiz.chosen}. Richtig ist: ${q.answer}. `)+q.explain;$$('[data-answer]').forEach((b,i)=>{b.disabled=true;if(opts[i]===q.answer)b.classList.add('selected');});$('#nextQuestion').hidden=false;$('#relearn').hidden=correct;if(!correct)showSupport('quizSupport',q.lesson);}}
let labelState={answers:Array(5).fill(''),hinted:false,helpOpen:false,recorded:false,message:'',correct:null};
function renderLabels(){const choices=['Notenkopf','Notenhals','Fähnchen','Balken','Punkt'];$('#main').innerHTML=`<section class="card"><div class="eyebrow">Beschriftungswerkstatt</div><h1>Ordne die Bestandteile zu.</h1><p>Wähle zu jeder Zahl den passenden Fachbegriff. Danach prüfst du deine Beschriftung.</p><svg class="anatomy" viewBox="0 0 520 240" role="img" aria-label="Zwei mit Balken verbundene Achtelnoten, die erste punktiert, und eine einzelne Achtelnote; fünf Bestandteile sind nummeriert"><g fill="currentColor"><ellipse cx="90" cy="160" rx="18" ry="12" transform="rotate(-20 90 160)"/><ellipse cx="230" cy="160" rx="18" ry="12" transform="rotate(-20 230 160)"/><circle cx="122" cy="160" r="5"/></g><path d="M106 160V45H246V160" fill="none" stroke="currentColor" stroke-width="5"/><path d="M106 45H246" stroke="currentColor" stroke-width="10"/><g stroke="var(--mint)" stroke-width="2"><path d="M80 172L30 208M106 100L165 100M160 45L175 18M124 165L151 207"/></g><g fill="var(--mint)" font-size="20"><text x="15" y="229">1</text><text x="170" y="105">2</text><text x="175" y="18">3</text><text x="155" y="226">4</text></g><path d="M366 160V40" stroke="currentColor" stroke-width="5"/><ellipse cx="350" cy="160" rx="18" ry="12" fill="currentColor" transform="rotate(-20 350 160)"/><path d="M366 40Q425 65 401 115Q415 78 366 68Z" fill="currentColor"/><path d="M399 77L458 40" stroke="var(--mint)" stroke-width="2"/><text x="465" y="42" fill="var(--mint)" font-size="20">5</text></svg><div class="labelRows">${[1,2,3,4,5].map(i=>`<label>Bestandteil ${i}<select id="part${i}"><option value="">Bitte wählen</option>${choices.map(c=>`<option ${labelState.answers[i-1]===c?'selected':''}>${c}</option>`).join('')}</select></label>`).join('')}</div><div class="row spaced"><button class="primary" id="checkLabels">Beschriftung prüfen</button><button id="labelHint">Tipp</button><button id="labelBack">Andere Übung</button></div><div id="labelResult" class="feedback ${labelState.correct===null?'':labelState.correct?'good':'bad'}" role="status">${labelState.message}</div><div id="labelHelp" class="tip" ${labelState.helpOpen?'':'hidden'}>Der ovale Teil ist der Kopf. Der senkrechte Strich ist der Hals. Der Balken verbindet kurze Noten. Der Punkt steht rechts neben dem Kopf. Ein Fähnchen sitzt am Hals einer einzelnen kurzen Note.</div><p class="legend">Diese Zuordnung zählt einmal zum selbstständigen Fortschritt. Mit Tipp übst du mit Unterstützung.</p><div id="labelSupport"></div></section>`;for(let i=1;i<=5;i++)$('#part'+i).value=labelState.answers[i-1];for(let i=1;i<=5;i++)$('#part'+i).onchange=()=>{stop();labelState.answers[i-1]=$('#part'+i).value;labelState.message='Antwort geändert. Prüfe deine Beschriftung erneut.';labelState.correct=null;$('#labelResult').textContent=labelState.message;$('#labelResult').className='feedback';};on('checkLabels',()=>{stop();labelState.answers=[1,2,3,4,5].map(i=>$('#part'+i).value);const expected=['Notenkopf','Notenhals','Balken','Punkt','Fähnchen'],missing=labelState.answers.some(v=>!v),correct=expected.filter((a,i)=>labelState.answers[i]===a).length;labelState.correct=missing?null:correct===5;labelState.message=missing?'Wähle zuerst alle fünf Begriffe.':(labelState.hinted?'Mit Hilfe geübt. ':'')+(correct===5?'Alles richtig beschriftet!':`${correct} von 5 richtig. Prüfe: 1 = Notenkopf, 2 = Notenhals, 3 = Balken, 4 = Punkt, 5 = Fähnchen.`);$('#labelResult').textContent=labelState.message;$('#labelResult').className='feedback '+(missing?'':correct===5?'good':'bad');if(!missing&&correct<5)showSupport('labelSupport',2);});on('labelHint',()=>{stop();if(!labelState.recorded)labelState.hinted=true;labelState.helpOpen=true;$('#labelHelp').hidden=false;});on('labelBack',()=>{quiz=null;setView('exerciseHub');});}
function newTask(){editIndex=-1;build=[];const pools=meter===2?[['h'],['q','q'],['qr','q'],['e','e','q'],['q','e','e'],['hr']]:meter===3?[['h','q'],['q','qr','q'],['e','e','q','q'],['q','e','e','q'],['hr','q']]:[['h','q','q'],['q','qr','q','q'],['e','e','q','h'],['q','h','q'],['hr','q','q']];if(advanced)pools.push(...(meter===2?[['qd','e'],['qrd','e'],['ed','s','q'],['s','s','s','s','q']]:meter===3?[['hd'],['qd','e','q'],['s','s','s','s','h'],['qrd','e','q']]:[['hd','q'],['qd','e','h'],['s','s','s','s','q','h'],['q','ed','s','h']]));const full=shuffle(pools)[0],cut=full.length===1?0:Math.max(1,Math.floor(Math.random()*full.length));fixed=full.slice(0,cut);task={solution:full.slice(cut),missing:meter*4-fixed.reduce((a,id)=>a+val(id,meter),0)};}
function renderBuilder(){const ids=[...fixed,...build],total=ids.reduce((a,id)=>a+val(id,meter),0),target=meter*4,replacing=editIndex>=0&&editIndex<build.length,available=target-total+(replacing?val(build[editIndex],meter):0);$('#main').innerHTML=`<div class="eyebrow">Taktwerkstatt</div><h1>${task?'Fülle die Lücke im Notensystem.':'Setze Noten in das Notensystem.'}</h1><section class="card"><div class="controls"><label>Taktart <select id="meter"><option value="2" ${meter===2?'selected':''}>2/4</option><option value="3" ${meter===3?'selected':''}>3/4</option><option value="4" ${meter===4?'selected':''}>4/4</option></select></label><label class="check"><input type="checkbox" id="advanced" ${advanced?'checked':''}> Punktierte Werte</label><button id="taskNew">Neue Lückenaufgabe</button><button id="free" class="${!task?'selected':''}">Freier Takt</button></div><ol class="buildSteps"><li>Tippe auf die <strong>gestrichelte Lücke</strong> im Notensystem.</li><li>Wähle unten eine <strong>Note oder Pause</strong>. Sie erscheint in der Lücke.</li><li>Prüfe den Takt und höre ihn an.</li></ol><p class="insertStatus" role="status">${replacing?`Du ersetzt deinen Eintrag ${editIndex+1}. Wähle unten das neue Zeichen.`:total===target?'Der Takt ist voll. Tippe eine eigene Note an, um sie zu ersetzen.':'Die nächste Note wird in die gestrichelte Lücke eingesetzt.'}</p><div id="builderScore">${staffScore(ids,meter,{interactive:true,fixedCount:fixed.length,gap:total<target,remaining:target-total})}</div><p class="legend">${fixed.length?'Graue Markierungen: vorgegeben. Mintfarbene Markierungen: deine Einträge. ':''}Eigene Zeichen kannst du antippen und ersetzen. Bei langen Takten die Notenzeile seitlich wischen.</p><div class="row"><button id="append" class="${!replacing?'selected':''}" ${total>=target?'disabled':''}>In die Lücke einsetzen</button><button id="deleteSelected" ${!replacing?'disabled':''}>Ausgewählten Eintrag entfernen</button><button id="undo" ${!build.length?'disabled':''}>Letzten Eintrag entfernen</button></div><h2 class="spaced">${fmt(total/4)} von ${meter} Schlägen eingesetzt</h2>${beats(meter)}<div class="countStrip ${meter===3?'three':''}" style="grid-template-columns:repeat(${target},1fr)">${Array.from({length:target},(_,i)=>`<span class="tick ${i<total?'filled':''}"></span>`).join('')}</div><div class="row"><button class="primary" id="checkBuild">Takt prüfen</button><button id="playBuild" ${!ids.length?'disabled':''}>Eingetragenen Rhythmus hören</button><button id="clearBuild" ${!build.length?'disabled':''}>Eigene Einträge löschen</button></div><div id="buildResult" class="feedback" role="status"></div><div id="builderSupport"></div><h3 class="spaced">Note auswählen → im System einsetzen</h3><div class="palette">${[...notes,...(advanced?dotted.slice(1):[])].map(n=>`<button data-add="${n.id}" ${val(n.id,meter)>available?'disabled':''}>${symbol(n.id)}<span>${n.name}</span><small>${duration(n.id,meter)}</small></button>`).join('')}</div><h3 class="spaced">Pause auswählen → im System einsetzen</h3><div class="palette">${[...rests,...(advanced?dottedRests.slice(1):[]),get('barrest')].map(n=>`<button data-add="${n.id}" ${val(n.id,meter)>available||n.id==='barrest'&&ids.length>(replacing?1:0)?'disabled':''}>${symbol(n.id)}<span>${n.name}</span><small>${duration(n.id,meter)}</small></button>`).join('')}</div><details><summary>Tipp zur Lücke</summary><p>${total===target?'Dein Takt ist gefüllt. Prüfe ihn und zähle beim Hören mit.':`Es fehlen ${fmt((target-total)/4)} Schläge. 1 Viertel = 2 Achtel = 4 Sechzehntel. Pausen zählen genauso viel wie die entsprechenden Noten.`}</p>${task?`<button id="showSolution">Eine mögliche Ergänzung zeigen</button><div id="solution"></div>`:''}<button id="meterLearn">Takte noch einmal lernen</button></details>${tip('Die Taktangabe steht links zwischen den Notenlinien. Die obere Zahl sagt, wie viele Viertelschläge hineinpassen. Der Taktstrich rechts schließt den Takt ab.')}</section>`;
 $('#meter').onchange=e=>{stop();meter=+e.target.value;editIndex=-1;build=[];fixed=[];if(task)newTask();renderBuilder();};$('#advanced').onchange=e=>{stop();advanced=e.target.checked;editIndex=-1;build=[];fixed=[];if(task)newTask();renderBuilder();};on('taskNew',()=>{stop();newTask();renderBuilder();});on('free',()=>{stop();task=null;fixed=[];build=[];editIndex=-1;renderBuilder();});on('append',()=>{editIndex=-1;renderBuilder();});on('deleteSelected',()=>{stop();if(replacing)build.splice(editIndex,1);editIndex=-1;renderBuilder();});bindSvgActions('[data-edit]',el=>{stop();editIndex=+el.dataset.edit;renderBuilder();});bindSvgActions('[data-gap]',()=>{editIndex=-1;renderBuilder();});$$('[data-add]').forEach(b=>b.onclick=()=>{stop();const id=b.dataset.add;if(val(id,meter)<=available){if(replacing)build[editIndex]=id;else build.push(id);editIndex=-1;renderBuilder();}});on('undo',()=>{stop();build.pop();editIndex=-1;renderBuilder();});on('clearBuild',()=>{stop();build=[];editIndex=-1;renderBuilder();});on('playBuild',()=>play(ids,meter,{target:$('#builderScore'),silentClick:true}));on('checkBuild',()=>{const good=total===target;$('#buildResult').className='feedback '+(good?'good':'bad');$('#buildResult').textContent=good?`Richtig: genau ${meter} Schläge. Höre den vollständigen Takt an und zähle mit.`:`Die Lücke ist noch nicht gefüllt: Es fehlen ${fmt((target-total)/4)} Schläge.`;if(!good)showSupport('builderSupport',3);});on('showSolution',()=>{$('#solution').innerHTML=staffScore([...fixed,...task.solution],meter)+'<p>Ein vollständiger Takt mit einer möglichen Ergänzung. Andere passende Werte sind ebenfalls richtig.</p>';});on('meterLearn',()=>{lesson=3;setView('learn');});}
let words=['Brot','Käse','Schokolade','Brot'];const wordIds={Brot:['q'],Käse:['e','e'],Schokolade:['s','s','s','s'],Ananas:['s','s','e']};
function renderRhythm(){const ids=words.flatMap(w=>wordIds[w]);$('#main').innerHTML=`<div class="eyebrow">Rhythmus sprechen & klatschen</div><h1>Brot, Käse, Schokolade und Ananas</h1><p class="muted">Wähle für jeden Schlag ein Wort. Die Noten im System passen sich sofort an.</p><div class="grid">${wordCard('Brot','Brot',['q'])}${wordCard('Käse','Kä – se',['e','e'])}${wordCard('Schokolade','Scho – ko – la – de',['s','s','s','s'])}${wordCard('Ananas','A – na – nas',['s','s','e'])}</div><section class="card spaced"><h2>Deinen Worttakt zusammenstellen</h2><div class="wordChoices">${words.map((w,i)=>`<label>Schlag ${i+1}<select data-wordbeat="${i}">${Object.keys(wordIds).map(name=>`<option ${w===name?'selected':''}>${name}</option>`).join('')}</select></label>`).join('')}</div><div id="wordScore">${staffScore(ids,4)}</div><p class="wordSentence">${words.join(' · ')}</p>${beats(4)}<button class="primary" id="wordTakt">Meinen Worttakt hören</button>${tip('Jede Wortgruppe dauert einen Viertelschlag. Käse teilt ihn in zwei Achtel, Schokolade in vier Sechzehntel. Ananas hat zwei Sechzehntel und eine Achtel: kurz – kurz – länger.')}<button class="tapPad" id="tap">Hier mitklopfen</button><p id="tapCount" class="legend" role="status">Klopffläche zum Mitmachen · keine automatische Rhythmusbewertung</p></section>`;bindHear();on('wordTakt',()=>play(ids,4,{target:$('#wordScore')}));$$('[data-wordbeat]').forEach(e=>e.onchange=()=>{stop();words[+e.dataset.wordbeat]=e.value;renderRhythm();});let taps=0;on('tap',()=>{taps++;$('#tapCount').textContent=`${taps} mal mitgeklopft. Halte den Puls gleichmäßig.`;const b=$('#tap');b.classList.add('playing');setTimeout(()=>b.classList.remove('playing'),110);});}

function bindSvgActions(selector,fn){$$(selector).forEach(e=>{e.onclick=()=>fn(e);e.onkeydown=event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();fn(e);}};});}
function scoreBeamGroups(ids,m,opts={}){const groups=[];let group=[],units=0;const flush=()=>{if(group.length>1)groups.push(group);group=[];};ids.forEach((id,i)=>{const n=id==='?'?null:get(id),u=n?val(id,m):(opts.unknownUnits||4),beat=Math.floor(units/4),short=n&&!n.rest&&['e','s'].includes(id[0])&&units+u<=(beat+1)*4;if(opts.boundaries?.includes(i))flush();if(!short)flush();else{if(group.length&&Math.floor(group[0].start/4)!==beat)flush();group.push({i,id,start:units});}units+=u;if(units%4===0)flush();});flush();return groups;}
function staffScore(ids,m=4,opts={}){const spacing=70,showGap=opts.gap&&Number.isFinite(opts.remaining),extra=showGap?130:40,w=Math.max(350,125+ids.length*spacing+extra),right=w-18,beamGroups=scoreBeamGroups(ids,m,opts),beamedIndices=new Set(beamGroups.flatMap(group=>group.map(n=>n.i)));
const lines=[50,65,80,95,110].map(y=>`<path d="M24 ${y}H${right}" stroke="currentColor" stroke-width="1.2" opacity=".65"/>`).join('');
let content=ids.map((id,i)=>{const x=125+i*spacing,unknown=id==='?',editable=opts.interactive&&i>=opts.fixedCount,selected=editable&&editIndex===i-opts.fixedCount;const glyph=unknown?'<text x="42" y="68" text-anchor="middle" fill="var(--accent)" font-size="32">?</text>':symbol(id,{staff:false,label:false,beamed:beamedIndices.has(i)}).replace(/^<svg[^>]*>/,'').replace(/<\/svg>$/,'');return `<g data-index="${i}" ${editable?`data-edit="${i-opts.fixedCount}" role="button" tabindex="0" aria-label="${get(id).name}, eigener Eintrag ${i-opts.fixedCount+1}, zum Ersetzen auswählen"`:''}><title>${unknown?'Gesuchtes Zeichen':get(id).name}</title>${opts.focusSlot===i?`<rect x="${x-28}" y="28" width="63" height="101" rx="9" fill="none" stroke="var(--accent)" stroke-width="3"/><text x="${x+3}" y="151" text-anchor="middle" fill="var(--accent)" font-size="13">Hörstelle</text>`:''}${opts.interactive?`<rect x="${x-27}" y="34" width="60" height="94" rx="8" fill="none" stroke="${editable?'var(--mint)':'var(--line)'}" stroke-width="${selected?4:1}"/>`:''}<g transform="translate(${x-42} 30)">${glyph}</g>${opts.interactive?`<text x="${x+2}" y="151" text-anchor="middle" fill="${editable?'var(--mint)':'var(--muted)'}" font-size="13">${editable?'dein Eintrag':'vorgegeben'}</text>`:''}</g>`;}).join('');
for(const group of beamGroups){const x=i=>136+i*spacing;content+=`<path data-beam="primary" d="M${x(group[0].i)} 50H${x(group.at(-1).i)}" stroke="currentColor" stroke-width="6"/>`;for(let j=0;j<group.length;j++){if(group[j].id[0]!=='s')continue;const first=j,last=j;let end=j;while(end+1<group.length&&group[end+1].id[0]==='s')end++;let from=x(group[j].i),to=x(group[end].i);if(end===j)to=from+(j===group.length-1?-20:20);content+=`<path data-beam="secondary" d="M${from} 61H${to}" stroke="currentColor" stroke-width="6"/>`;j=end;}}
if(showGap){const x=ids.length?125+(ids.length-1)*spacing+40:110;content+=`<g data-gap="true" role="button" tabindex="0" aria-label="Lücke auswählen: ${fmt(opts.remaining/4)} Schläge fehlen"><rect x="${x}" y="30" width="108" height="100" rx="12" fill="var(--panel)" fill-opacity=".65" stroke="var(--accent)" stroke-width="2.5" stroke-dasharray="6 4"/><text x="${x+54}" y="74" text-anchor="middle" fill="var(--accent)" font-size="26">+</text><text x="${x+54}" y="105" text-anchor="middle" fill="var(--accent)" font-size="14">Hier einsetzen</text><text x="${x+54}" y="151" text-anchor="middle" fill="var(--accent)" font-size="14">${fmt(opts.remaining/4)} ${opts.remaining<=4?'Schlag':'Schläge'} frei</text></g>`;}
if(opts.boundaries){for(let i=1;i<ids.length;i++){const x=125+(i-.5)*spacing,chosen=opts.boundaries.includes(i);content+=`<g ${opts.readonly?'':`data-boundary="${i}" tabindex="0" role="button"`} aria-label="Taktstrich nach Zeichen ${i} ${chosen?'entfernen':'setzen'}"><rect x="${x-16}" y="30" width="32" height="103" fill="transparent"/><path d="M${x} 48V112" stroke="${chosen?'var(--mint)':'var(--line)'}" stroke-width="${chosen?4:2}" ${chosen?'':'stroke-dasharray="3 4"'}/><circle cx="${x}" cy="145" r="11" fill="var(--panel2)" stroke="${chosen?'var(--mint)':'var(--line)'}"/><text x="${x}" y="150" text-anchor="middle" fill="currentColor" font-size="16">${chosen?'✓':'+'}</text></g>`;}}
return `<div class="scoreScroll" tabindex="0" aria-label="Notensystem, ${m}/4-Takt; bei Bedarf seitlich scrollen"><svg class="musicScore" viewBox="0 0 ${w} 170" style="min-width:${w}px" ${opts.interactive||opts.boundaries&&!opts.readonly?'role="group"':'role="img"'} aria-label="${m}/4-Rhythmus: ${ids.map(id=>id==='?'?'fehlendes Zeichen':get(id).name).join(', ')||'leerer Takt'}"><text x="25" y="20" fill="var(--muted)" font-size="14">Rhythmuszeile</text>${lines}<g fill="currentColor" font-size="32" font-weight="700" text-anchor="middle"><text x="60" y="77">${m}</text><text x="60" y="108">4</text></g><path d="M90 50V110 M${right} 50V110" stroke="currentColor" stroke-width="2"/>${content}</svg></div>`;}
let detectMode='errors',detectMeter=4,detectAdvanced=false,detectRound=null,detectNumber=1,detectScore=0,tabooPattern=null;
const measureTotal=(ids,m)=>ids.reduce((a,id)=>a+val(id,m),0);
function rhythmPool(m,adv=false){let p=m===3?[['h','q'],['q','q','q'],['q','qr','q'],['e','e','q','q'],['q','e','er','q'],['s','s','s','s','q','q'],['q','hr']]:[['h','q','q'],['q','q','q','q'],['q','qr','q','q'],['e','e','q','h'],['q','q','er','e','q'],['q','s','s','s','s','h'],['q','hr','q']];if(adv)p.push(...(m===3?[['hd'],['qd','e','q'],['q','ed','s','q'],['q','qrd','e']]:[['hd','q'],['qd','e','h'],['h','ed','s','q'],['q','qrd','e','q']]));return p;}
function rhythmKey(ids){return ids.map(id=>[get(id).rest?1:0,val(id,detectMeter)]).map(x=>x.join(':')).join('|');}
function newDetectiveRound(reset=false){if(reset){detectNumber=1;detectScore=0;tabooPattern=null;}const pool=rhythmPool(detectMeter,detectAdvanced),ids=[...shuffle(pool)[0]];detectRound={ids,answered:false,heard:false};if(detectMode==='errors'){const kind=shuffle(['valid','short','long'])[0];if(kind==='short'){if(ids.length>1)ids.pop();else ids[0]='h';}if(kind==='long')ids.push(shuffle(['q','e','qr'])[0]);detectRound.answer=measureTotal(ids,detectMeter)===detectMeter*4?'valid':measureTotal(ids,detectMeter)<detectMeter*4?'short':'long';}
if(detectMode==='taboo'){tabooPattern ||= [...shuffle(pool)[0]];if(Math.random()<.45)detectRound.ids=[...tabooPattern];else detectRound.ids=[...shuffle(pool.filter(p=>rhythmKey(p)!==rhythmKey(tabooPattern)))[0]];detectRound.answer=rhythmKey(detectRound.ids)===rhythmKey(tabooPattern)?'taboo':'echo';}
if(detectMode==='pause'){startPauseRound(reset);}
if(detectMode==='bars'){detectRound.ids=[...ids,...shuffle(pool)[0]];detectRound.boundaries=[];detectRound.expected=[ids.length];}}
function renderDetective(){if(detectMode==='pause'){renderPauseLab();return;}detectRound ||= (newDetectiveRound(true),detectRound);const r=detectRound,m=detectMeter,names={errors:'Taktfehler finden',taboo:'Verbotener Rhythmus',pause:'Pause oder Ton?',bars:'Taktstriche setzen'};let body='';
if(detectMode==='errors')body=`<h2>Passt dieser Takt zur Taktangabe?</h2><p>Prüfe Noten <strong>und</strong> Pausen. Wähle: vollständig, zu kurz oder zu lang. Die Taktangabe links gilt für diesen ganzen Takt.</p><div id="detectScore">${staffScore(r.ids,m)}</div><button id="detectListen">Geschriebenen Rhythmus hören</button><div class="answerGrid"><button data-detectanswer="valid">✓ Vollständiger Takt</button><button data-detectanswer="short">Zu kurz: Es fehlt Zeit</button><button data-detectanswer="long">Zu lang: Zu viel Zeit</button></div>`;
if(detectMode==='taboo')body=`<h2>Merke dir diesen verbotenen Rhythmus.</h2><p>Nur in diesem Spiel gilt: Bei <strong>genau diesem Muster</strong> nicht nachklatschen! Andere vollständige Takte darfst du als Echo klatschen. Beachte auch die Pausen.</p><div id="tabooScore">${staffScore(tabooPattern,m)}</div><button id="tabooListen">Verbotenes Muster anhören</button><h3 class="spaced">Was hörst du jetzt?</h3><p>Der neue Rhythmus bleibt bis zur Antwort verborgen.</p>${beats(m)}<button class="primary" id="detectListen">Neuen Rhythmus hören</button><div class="answerGrid"><button data-detectanswer="taboo" ${!r.heard?'disabled':''}>Verboten – ich schweige</button><button data-detectanswer="echo" ${!r.heard?'disabled':''}>Anderes Muster – ich klatsche nach</button></div><div id="revealedScore"></div>`;
if(detectMode==='pause'){const masked=r.ids.map((id,i)=>i===r.slot?'?':id);body=`<h2>Ist das fehlende Zeichen eine Note oder Pause?</h2><p>Höre den vollständigen Takt. Am Fragezeichen fehlt <strong>ein Viertelschlag</strong>. Achte auf den ${r.slot+1}. Schlag.</p><div id="detectScore">${staffScore(masked,m)}</div>${beats(m)}<button class="primary" id="detectListen">Vollständigen Takt hören</button><div class="answerGrid"><button data-detectanswer="q" ${!r.heard?'disabled':''}>${symbol('q')}Viertelnote – hier klingt ein Ton</button><button data-detectanswer="qr" ${!r.heard?'disabled':''}>${symbol('qr')}Viertelpause – hier ist Stille</button></div><div id="revealedScore"></div>`;}
if(detectMode==='bars')body=`<h2>Teile die Notenzeile in zwei Takte.</h2><p>Tippe auf ein <strong>+</strong> zwischen den Zeichen, um einen Taktstrich zu setzen oder wieder zu entfernen. Jeder Takt braucht genau ${m} Viertelschläge. Anfangs- und Endstrich stehen schon fest.</p><div id="detectScore">${staffScore(r.ids,m,{boundaries:r.boundaries})}</div><p class="legend">Bei langen Zeilen seitlich wischen. Die Taktangabe am Anfang gilt für beide Takte.</p><div class="row"><button class="primary" id="checkBars">Meine Taktstriche prüfen</button><button id="detectListen">Die ganze Zeile hören</button></div>`;
$('#main').innerHTML=`<div class="eyebrow">Rhythmusdetektiv</div><h1>Hören, entdecken, entscheiden</h1><div class="detectTabs" aria-label="Interaktive Spiele">${Object.entries(names).map(([id,name])=>`<button data-detectmode="${id}" class="${id===detectMode?'selected':''}">${name}</button>`).join('')}</div><section class="card spaced"><div class="controls"><label>Taktart <select id="detectMeter"><option value="3" ${m===3?'selected':''}>3/4</option><option value="4" ${m===4?'selected':''}>4/4</option></select></label><label class="check"><input id="detectAdvanced" type="checkbox" ${detectAdvanced?'checked':''}> Mit punktierten Werten</label><span class="pill">Aufgabe ${detectNumber} · ${detectScore} richtig</span></div><div class="spaced">${body}</div><button id="detectHint">Tipp anzeigen</button><div id="detectHintText" class="tip" hidden></div><div id="detectResult" class="feedback" role="status"></div><div id="detectSupport"></div><button id="detectNext" class="primary" ${!r.answered?'hidden':''}>Nächste Aufgabe</button><details><summary>Regeln und Merksätze</summary><p>Bei Taktfehlern zählt die Summe der Werte. Beim verbotenen Rhythmus zählt das genaue Muster einschließlich aller Pausen. Eine Pause klingt selbst nicht – man erkennt ihre Stille im laufenden Takt. Auch während der Pause geht der Puls weiter.</p></details></section>`;
$$('[data-detectmode]').forEach(b=>b.onclick=()=>{stop();detectMode=b.dataset.detectmode;newDetectiveRound(true);renderDetective();});$('#detectMeter').onchange=e=>{stop();detectMeter=+e.target.value;newDetectiveRound(true);renderDetective();};$('#detectAdvanced').onchange=e=>{stop();detectAdvanced=e.target.checked;newDetectiveRound(true);renderDetective();};on('tabooListen',()=>play(tabooPattern,m,{silentClick:true,target:$('#tabooScore')}));on('detectListen',()=>{r.heard=true;$$('[data-detectanswer]').forEach(b=>b.disabled=r.answered);play(r.ids,m,{silentClick:true,hideEvents:detectMode==='taboo'||detectMode==='pause',target:$('#detectScore')});});on('detectHint',()=>{$('#detectHintText').hidden=false;$('#detectHintText').textContent=detectMode==='errors'?`Rechne die Werte zusammen. Eine Viertel ist 1, eine Halbe 2 und eine Achtel ½ Schlag. Der Takt braucht ${m} Schläge.`:detectMode==='taboo'?'Höre das gemerkte Muster noch einmal. Tonanfänge, Längen und stille Stellen müssen genau übereinstimmen.':detectMode==='pause'?'Zähle ab dem ersten Schlag mit. Gibt es am gesuchten Schlag einen Tonanfang oder Stille?':'Beginne links zu zählen. Sobald die Summe '+m+' Schläge erreicht, braucht die Zeile einen Taktstrich.';});$$('[data-detectanswer]').forEach(b=>b.onclick=()=>{if(r.answered||!r.heard&&(detectMode==='pause'||detectMode==='taboo'))return;answerDetective(b.dataset.detectanswer===r.answer);});bindSvgActions('[data-boundary]',e=>{if(r.answered)return;stop();const n=+e.dataset.boundary;r.boundaries=r.boundaries.includes(n)?r.boundaries.filter(x=>x!==n):[...r.boundaries,n].sort((a,b)=>a-b);renderDetective();});on('checkBars',()=>{if(r.answered)return;answerDetective(checkBarBoundaries(r.ids,m,r.boundaries));});on('detectNext',()=>{stop();detectNumber++;newDetectiveRound();renderDetective();});}
function checkBarBoundaries(ids,m,boundaries){const edges=[0,...boundaries,ids.length];return edges.length===3&&edges.slice(1).every((edge,i)=>measureTotal(ids.slice(edges[i],edge),m)===m*4);}
function answerDetective(correct){recordSkill(detectMode==='errors'||detectMode==='bars'?3:4,correct,'Rhythmusdetektiv '+detectMode);const r=detectRound;stop();r.answered=true;if(correct)detectScore++;let explanation='';if(detectMode==='errors'){const total=measureTotal(r.ids,detectMeter)/4;explanation=`Die Zeichen ergeben ${fmt(total)} Schläge. Im ${detectMeter}/4-Takt sind ${detectMeter} nötig. `+(r.answer==='valid'?'Dieser Takt ist vollständig.':r.answer==='short'?`Es fehlen ${fmt(detectMeter-total)} Schläge.`:`Es sind ${fmt(total-detectMeter)} Schläge zu viel.`);}if(detectMode==='taboo'){explanation=r.answer==='taboo'?'Genau das gemerkte Muster! Hier bleibst du still.':'Ein anderes Muster. Dieses darfst du nachklatschen.';$('#revealedScore').innerHTML=staffScore(r.ids,detectMeter);}if(detectMode==='pause'){explanation=r.answer==='qr'?`Am ${r.slot+1}. Schlag ist eine Viertelpause: ein Schlag Stille.`:`Am ${r.slot+1}. Schlag erklingt eine Viertelnote.`;$('#revealedScore').innerHTML=staffScore(r.ids,detectMeter);}if(detectMode==='bars'){explanation=`Der innere Taktstrich gehört nach Zeichen ${r.expected[0]}. Dann ergeben beide Takte genau ${detectMeter} Schläge.`;$('#detectScore').innerHTML=staffScore(r.ids,detectMeter,{boundaries:r.expected,readonly:true});}$('#detectResult').className='feedback '+(correct?'good':'bad');$('#detectResult').textContent=(correct?'Richtig! ':'Noch nicht. ')+explanation;$$('[data-detectanswer]').forEach(b=>b.disabled=true);$('#detectNext').hidden=false;if(!correct)showSupport('detectSupport',detectMode==='bars'||detectMode==='errors'?3:4);}

let pauseLevel=1,pauseTutorial=true,pauseQueue=[],pauseKey='',pauseCompleted=0;const pauseBanks=new Map();
function noteRestPartner(id){return id.endsWith('d')?id[0]+'rd':id+'r';}
function pauseBank(m,level){const key=m+':'+level;if(pauseBanks.has(key))return pauseBanks.get(key);const bases=level===1?[Array(m).fill('q')]:level===2?(m===3?[['h','q'],['h','e','e'],['q','e','e','q'],['e','e','e','e','q']]:[['h','q','q'],['h','h'],['h','e','e','q'],['q','e','e','e','e','q'],['h','e','e','e','e']]):(m===3?[['qd','e','q'],['q','ed','s','q'],['q','s','s','s','s','q'],['ed','s','ed','s','q'],['h','s','s','s','s']]:[['qd','e','h'],['h','ed','s','q'],['q','q','s','s','s','s','q'],['ed','s','ed','s','h'],['hd','q']]);const unique=new Map();
 for(const base of bases)for(const direction of [base,[...base].reverse()])for(let rotate=0;rotate<base.length;rotate++){const pattern=direction.slice(rotate).concat(direction.slice(0,rotate));for(let mask=0;mask<(1<<pattern.length)-1;mask++){const ids=pattern.map((id,i)=>mask&(1<<i)?noteRestPartner(id):id);for(let slot=0;slot<ids.length;slot++){const allowed=level===1||level===2&&['h','e'].includes(pattern[slot])||level===3&&['s','qd','ed','hd'].includes(pattern[slot]);if(!allowed)continue;const key=ids.join(',')+':'+slot;const start=measureTotal(ids.slice(0,slot),m);unique.set(key,{key:m+':'+level+':'+key,ids,slot,answer:ids[slot],start,end:start+val(ids[slot],m),note:pattern[slot]});}}}
 let candidates=[...unique.values()];if(level>1){const types=[...new Set(candidates.map(c=>c.answer))],buckets=types.map(t=>shuffle(candidates.filter(c=>c.answer===t))),selected=[],limit=level===2?80:100;while(selected.length<limit&&buckets.some(b=>b.length))for(const bucket of buckets)if(bucket.length&&selected.length<limit)selected.push(bucket.pop());candidates=selected;}pauseBanks.set(key,candidates);return candidates;}
function startPauseRound(reset=false){const key=detectMeter+':'+pauseLevel;if(reset||pauseKey!==key){pauseKey=key;pauseQueue=shuffle(pauseBank(detectMeter,pauseLevel)).sort((a,b)=>pauseDifficulty(a)-pauseDifficulty(b));pauseCompleted=0;}const next=pauseQueue.shift();detectRound=next?{...next,ids:[...next.ids],answered:false,heard:false,done:false}:{done:true,answered:false};}
function countName(unit){return String(Math.floor(unit/4)+1)+(['',' e',' und',' a'][unit%4]||'');}
function pauseWindowText(r){return r.end-r.start===4&&r.start%4===0?'Schlag '+(r.start/4+1):`ab „${countName(r.start)}“ · ${duration(r.answer,detectMeter)} lang`;}
function pauseTimeline(r,m,showAnswer=false){const end=m*4;return `<div class="pauseTimeline" style="--beats:${m}" aria-label="Der gelbe Bereich ist die gesuchte Hörstelle">${Array.from({length:end},(_,i)=>`<span data-pulse="${i}" class="pulseCell ${i>=r.start&&i<r.end?'targetCell':''}">${i%4===0?Math.floor(i/4)+1:''}</span>`).join('')}</div><p class="targetCaption">Gelbe Hörstelle: <strong>${pauseWindowText(r)}</strong></p>`;}
function pauseProgress(r,{units}){const active=units>=r.start&&units<r.end;$$('[data-pulse]').forEach(e=>e.classList.toggle('active',units>=+e.dataset.pulse&&units<+e.dataset.pulse+1));const mark=$('#pauseFocus');if(mark)mark.classList.toggle('listening',active);$('#pauseListening').textContent=units<0?'Erst die Klicks mitzählen. Danach beginnt der Takt.':active?'Jetzt kommt die gelbe Hörstelle. Achte auf Klang oder Stille.':'Zähle mit. Achte auf den gelben Bereich.';}
function renderPauseLab(){const r=detectRound;if(!r||!('done'in r)){startPauseRound(true);return renderPauseLab();}const bank=pauseBank(detectMeter,pauseLevel),totalTasks=[3,4].reduce((sum,m)=>sum+[1,2,3].reduce((a,l)=>a+pauseBank(m,l).length,0),0);let body='';
if(r.done)body=`<h2>Alle ${bank.length} Aufgaben dieser Stufe geschafft!</h2><p>${detectScore} richtig. Wähle eine andere Stufe oder Taktart für neue Hörstellen.</p><button id="pauseRestart" class="primary">Diese Stufe erneut üben</button>`;
else if(pauseTutorial)body=`<div class="eyebrow">Erst ein Beispiel gemeinsam</div><h2>Höre auf den gelben Bereich.</h2><p>Du hörst einen Takt. An der <strong>gelb markierten Stelle</strong> fehlt ein Zeichen. Deine Aufgabe: Entscheide, ob dort ein Ton klingt oder Stille ist.</p><div class="two"><div class="value"><strong>Ein Ton klingt</strong>${symbol('q')}<p>Das ist eine Note. Ein Ton beginnt und wird gehalten.</p></div><div class="value"><strong>Es ist still</strong>${symbol('qr')}<p>Das ist eine Pause. Du zählst weiter, spielst aber nichts.</p></div></div><h3 class="spaced">Beispiel im ${detectMeter}/4-Takt: ${detectMeter===3?'Ton – Pause – Ton':'Ton – Pause – Ton – Ton'}</h3><div id="pauseDemoScore">${staffScore(Array.from({length:detectMeter},(_,i)=>i===1?'qr':'q'),detectMeter,{focusSlot:1})}</div><p><strong>Beim zweiten Schlag ist es still.</strong> Dort steht deshalb eine Viertelpause. Die Note auf dem ersten Schlag wird nicht über den zweiten Schlag gehalten.</p><button id="pauseDemo" class="primary">Beispiel hören und mitsehen</button><p id="pauseDemoStatus" class="feedback" role="status">Erst ${detectMeter} Zählklicks, dann der Takt. Zähle ${Array.from({length:detectMeter},(_,i)=>i+1).join(' – ')} mit.</p>${tip('Klang = Note. Stille = Pause. Eine lange Note kann über mehrere Schläge klingen – ohne neuen Tonanfang.')}<button id="pauseStart" class="primary">Verstanden – jetzt selbst probieren</button>`;
else {const rest=get(r.answer).rest,base=r.note,restId=noteRestPartner(base),masked=r.ids.map((id,i)=>i===r.slot?'?':id);body=`<div class="eyebrow">Aufgabe ${pauseCompleted+1} von ${bank.length} · ${detectScore} richtig</div><h2>Was passiert an der gelben Hörstelle?</h2><ol class="buildSteps"><li>Sieh dir den <strong>gelben Bereich</strong> an: ${pauseWindowText(r)}.</li><li>Tippe auf <strong>„Takt hören“</strong>. Zähle zuerst die Klicks mit; danach beginnt der Takt.</li><li>Höre an der gelben Stelle: <strong>Klingt ein Ton oder ist es still?</strong> Wähle anschließend das passende Zeichen.</li></ol><div id="pauseFocus" class="pauseFocus"><div id="pauseTaskScore">${staffScore(masked,detectMeter,{focusSlot:r.slot,unknownUnits:val(r.answer,detectMeter)})}</div>${pauseTimeline(r,detectMeter)}</div>${pauseLevel>1?`<p class="legend">${pauseLevel===2?'Achtel zählen: 1 – und – 2 – und. Eine halbe Note klingt zwei Schläge lang.':'Sechzehntel zählen: 1 – e – und – a. Der Punkt verlängert um die Hälfte.'}</p>`:''}<p class="legend">Der fehlende Wert ist ${duration(r.answer,detectMeter)} lang. Es geht hier um Klang oder Stille – beide Antwortzeichen haben dieselbe Dauer.</p><button id="pauseHear" class="primary">▶ Takt hören</button><p id="pauseListening" class="feedback" role="status">Höre erst den ganzen Takt. Danach kannst du antworten.</p><div class="answerGrid pauseAnswers"><button data-pauseanswer="${base}" ${!r.heard||r.answered?'disabled':''}><strong>Ein Ton klingt</strong>${symbol(base)}<span>${get(base).name} · ${duration(base,detectMeter)}</span></button><button data-pauseanswer="${restId}" ${!r.heard||r.answered?'disabled':''}><strong>Es ist still</strong>${symbol(restId)}<span>${get(restId).name} · ${duration(restId,detectMeter)}</span></button></div><button id="pauseTip">Ich brauche einen Tipp</button><div id="pauseHelp" class="tip" hidden></div><div id="pauseResult" class="feedback" role="status"></div><div id="pauseSupport"></div><div id="pauseSolution"></div><div class="row"><button id="pauseSolutionHear" hidden>Takt mit Lösung noch einmal hören</button><button id="pauseNext" class="primary" ${!r.answered?'hidden':''}>Nächste neue Aufgabe</button></div>`;}
$('#main').innerHTML=`<div class="eyebrow">Rhythmusdetektiv · Hörtraining</div><h1>Klingt ein Ton oder ist es still?</h1><div class="detectTabs">${[['errors','Taktfehler finden'],['taboo','Verbotener Rhythmus'],['pause','Ton oder Stille?'],['bars','Taktstriche setzen']].map(([id,label])=>`<button data-pausemode="${id}" class="${id==='pause'?'selected':''}">${label}</button>`).join('')}</div><section class="card spaced"><div class="controls"><label>Stufe <select id="pauseLevel">${[[1,'1 · Einstieg: Viertel'],[2,'2 · Halbe & Achtel'],[3,'3 · Sechzehntel & Punkt']].map(([n,label])=>`<option value="${n}" ${pauseLevel===n?'selected':''}>${label}</option>`).join('')}</select></label><label>Taktart <select id="pauseMeter"><option value="3" ${detectMeter===3?'selected':''}>3/4</option><option value="4" ${detectMeter===4?'selected':''}>4/4</option></select></label><button id="pauseExplain">Beispiel & Anleitung</button></div><p class="legend spaced">${totalTasks} vorbereitete Hör-Aufgaben · ${bank.length} in dieser Stufe und Taktart · keine Wiederholung bis zum Ende der Runde.</p><div class="spaced">${body}</div></section>`;
if(!pauseTutorial&&!r.done){const scroller=$('#pauseTaskScore .scoreScroll');scroller?.scrollTo?.({left:Math.max(0,125+r.slot*70-(scroller.clientWidth||300)/2),behavior:'instant'});}$$('[data-pausemode]').forEach(b=>b.onclick=()=>{stop();detectMode=b.dataset.pausemode;newDetectiveRound(true);renderDetective();});$('#pauseLevel').onchange=e=>{stop();pauseLevel=+e.target.value;detectNumber=1;detectScore=0;startPauseRound(true);renderPauseLab();};$('#pauseMeter').onchange=e=>{stop();detectMeter=+e.target.value;detectNumber=1;detectScore=0;startPauseRound(true);renderPauseLab();};on('pauseExplain',()=>{stop();pauseTutorial=true;renderPauseLab();});on('pauseStart',()=>{stop();pauseTutorial=false;renderPauseLab();});on('pauseRestart',()=>{stop();detectNumber=1;detectScore=0;startPauseRound(true);renderPauseLab();});on('pauseDemo',()=>play(Array.from({length:detectMeter},(_,i)=>i===1?'qr':'q'),detectMeter,{leadIn:true,silentClick:true,target:$('#pauseDemoScore'),onProgress({units}){$('#pauseDemoStatus').textContent=units<0?`${detectMeter} Klicks mitzählen: Gleich beginnt der Takt.`:units>=4&&units<8?'2: Jetzt ist es still. Das ist die Viertelpause.':`Schlag ${Math.min(detectMeter,Math.floor(units/4)+1)}: Ein Ton klingt.`;}}));
on('pauseHear',()=>{if(r.answered)return;$$('[data-pauseanswer]').forEach(b=>b.disabled=true);r.heard=false;play(r.ids,detectMeter,{leadIn:true,silentClick:true,hideEvents:true,onProgress:progress=>pauseProgress(r,progress),onComplete(){r.heard=true;$$('[data-pauseanswer]').forEach(b=>b.disabled=false);$('#pauseFocus').classList.remove('listening');$('#pauseListening').textContent='Jetzt wählen: Hat es im gelben Bereich geklungen oder war es still? Du kannst den Takt auch noch einmal hören.';}});});
on('pauseTip',()=>{$('#pauseHelp').hidden=false;$('#pauseHelp').textContent=`Zähle nach den Anfangsklicks mit. Die gelbe Hörstelle beginnt ${r.start===0?'direkt am Taktanfang':'bei „'+countName(r.start)+'“'} und dauert ${duration(r.answer,detectMeter)}. Ein gehaltener Ton zählt auch als Klang. Bei einer Pause bleibt die ganze Hörstelle still. Stelle das Tempo unten langsamer, wenn nötig.`;});
$$('[data-pauseanswer]').forEach(b=>b.onclick=()=>{if(!r.heard||r.answered)return;stop();r.answered=true;pauseCompleted++;const correct=b.dataset.pauseanswer===r.answer;recordSkill(1,correct,'Pause im laufenden Takt');if(correct)detectScore++;$('#pauseResult').className='feedback '+(correct?'good':'bad');$('#pauseResult').textContent=(correct?'Richtig! ':'Noch nicht. ')+(get(r.answer).rest?`An der gelben Stelle ist ${duration(r.answer,detectMeter)} lang Stille. Deshalb gehört dort eine ${sentenceName(get(r.answer).name)} hin.`:`An der gelben Stelle klingt ein Ton ${duration(r.answer,detectMeter)} lang. Deshalb gehört dort eine ${sentenceName(get(r.answer).name)} hin.`);$('#pauseSolution').innerHTML='<h3>So sieht der vollständige Takt aus:</h3>'+staffScore(r.ids,detectMeter,{focusSlot:r.slot});$$('[data-pauseanswer]').forEach(btn=>{btn.disabled=true;if(btn.dataset.pauseanswer===r.answer)btn.classList.add('selected');});$('#pauseNext').hidden=false;$('#pauseSolutionHear').hidden=false;if(!correct)showSupport('pauseSupport',1);});on('pauseSolutionHear',()=>play(r.ids,detectMeter,{leadIn:true,silentClick:true,target:$('#pauseSolution')}));on('pauseNext',()=>{stop();detectNumber++;startPauseRound();renderPauseLab();});}

