function guideCard(i){const c=guideConfig(i),step=guideSteps[i];return `<section class="guided spaced"><h2>Dein Lernweg in diesem Kapitel</h2><div class="guideSteps">${['Verstehen','Beispiel','Gemeinsam','Selbst üben'].map((label,n)=>`<button data-guide-step="${n}" class="${step===n?'selected':''}">${n+1} · ${label}</button>`).join('')}</div>${step===0?'<p>Lies die Erklärung und probiere die Bilder und Klangbeispiele oben aus. Dann geht es mit einem vorgemachten Takt weiter.</p><button id="guideForward" class="primary">Erklärung gelesen – Beispiel zeigen</button>':step===1?`<div id="guideScore">${staffScore(c.ids,c.m)}</div><p>${c.example}</p><button id="guideHear" class="primary">Beispiel mit Zählhilfe hören</button> <button id="guideForward">Jetzt gemeinsam lösen</button>`:step===2?`<h3>${c.q}</h3><p class="muted">${c.example}</p><div class="answerGrid">${c.options.map((a,n)=>`<button data-guide-answer="${n}">${a}</button>`).join('')}</div><div id="guideFeedback" class="feedback" role="status"></div><button id="guideForward" class="primary" ${guidePassed[i]?'':'hidden'}>Jetzt selbst üben</button>`:`<p>Du hast das Beispiel verstanden. Jetzt kommen neue Aufgaben. Bei Fehlern bekommst du passende Hilfe.</p><button id="guidePractice" class="primary">Übungen zu diesem Kapitel starten</button>`}</section>`;}
