function showSupport(id,topic){const c=supportConfig(topic),target=$('#'+id);target.innerHTML=`<section class="supportCard"><h3>Noch einmal einfacher</h3><p>${c.text}</p><div id="supportScore">${staffScore(c.ids,c.m)}</div><button id="supportHear">Einfaches Beispiel hören</button><p class="spaced"><strong>${c.q}</strong></p><div class="row">${c.choices.map((a,i)=>`<button data-support-answer="${i}">${a}</button>`).join('')}</div><div id="supportFeedback" class="feedback" role="status"></div><button id="supportLearn">Erklärung dazu öffnen</button></section>`;on('supportHear',()=>play(c.ids,c.m,{leadIn:true,silentClick:true,target:$('#supportScore')}));$$('[data-support-answer]').forEach(b=>b.onclick=()=>{$('#supportFeedback').textContent=(c.choices[+b.dataset.supportAnswer]===c.answer?'Richtig! ':'Noch einmal überlegen. ')+c.why;});on('supportLearn',()=>{lesson=topic;guideSteps[lesson]=1;setView('learn');});}
