function onsetTimes(ids,m,seconds){let u=0;const times=[];ids.forEach(id=>{if(!get(id).rest)times.push(u/4*seconds);u+=val(id,m);});return times;}
function gradeTaps(expected,actual,seconds,relaxed=true){const minGap=expected.length>1?Math.min(...expected.slice(1).map((x,i)=>x-expected[i])):seconds;const tolerance=Math.max(.06,Math.min(relaxed ? .24 : .15,minGap*.48));const unused=new Set(actual.map((_,i)=>i)),deviations=[];expected.forEach(t=>{let best=-1,dist=Infinity;unused.forEach(i=>{const d=Math.abs(actual[i]-t);if(d<dist){best=i;dist=d;}});if(best>=0&&dist<=tolerance){unused.delete(best);deviations.push(dist);}});return {matched:deviations.length,total:expected.length,missed:expected.length-deviations.length,extra:unused.size,tolerance};}
