function renderTap(){$('#main').innerHTML=`<div class="eyebrow">Hören & nachklopfen</div><h1>Dein Rhythmus-Echo</h1><section class="card"><div class="controls"><label>Takt <select id="tapMeter"><option value="3" ${tapMeter===3?'selected':''}>3/4</option><option value="4" ${tapMeter===4?'selected':''}>4/4</option></select></label><label>Stufe <select id="tapLevel">${[[1,'1 · Viertel & Halbe'],[2,'2 · Mit Achteln'],[3,'3 · Sechzehntel & Punkt']].map(([i,s])=>`<option value="${i}" ${tapLevel===i?'selected':''}>${s}</option>`).join('')}</select></label><label class="check"><input id="tapRelaxed" type="checkbox" ${tapRelaxed?'checked':''}> Entspannte Toleranz</label><button id="tapNew">Neuer Rhythmus</button></div><ol class="buildSteps"><li>Höre das Beispiel. Klatsche bei jedem <strong>Tonanfang einmal</strong>.</li><li>Tippe „Nachklopfen starten“. Zähle die ${tapMeter} Klicks mit.</li><li>Klopfe danach auf die große Fläche. Bei einer Pause nicht klopfen; bei einer langen Note nur am Anfang.</li></ol><div id="tapScore">${staffScore(tapPattern,tapMeter)}</div>${beats(tapMeter)}<div class="row"><button class="primary" id="tapExample">Beispiel hören</button><button id="tapRecord">Nachklopfen starten</button></div><p id="tapStatus" class="feedback" role="status">Erst anhören, dann nachklopfen. Du brauchst kein Mikrofon.</p><button id="tapPad" class="tapPad">Hier nachklopfen</button><div id="tapResult" class="feedback" role="status"></div><p class="legend">Die Rückmeldung ist eine Orientierung: Ton-Ausgabe und Berührung können je nach Gerät verzögert sein. Beginne langsam und mit entspannter Toleranz.</p>${tip('Ein Klopfer pro Tonanfang. Eine halbe Note hält zwei Schläge – sie bekommt trotzdem nur einen Klopfer.')}</section>`;$('#tapMeter').onchange=e=>{tapMeter=+e.target.value;newTapPattern();};$('#tapLevel').onchange=e=>{tapLevel=+e.target.value;newTapPattern();};$('#tapRelaxed').onchange=e=>tapRelaxed=e.target.checked;on('tapNew',newTapPattern);on('tapExample',()=>play(tapPattern,tapMeter,{leadIn:true,silentClick:true,target:$('#tapScore')}));on('tapRecord',()=>{tapTimes=[];tapPhase='waiting';$('#tapResult').textContent='';$('#tapStatus').textContent='Klicks mitzählen. Danach selbst klopfen – der Takt wird dann nicht vorgespielt.';const seconds=60/Number($('#tempo').value);play([{u:tapMeter*4,rest:true}],tapMeter,{leadIn:true,silentClick:true,hideEvents:true,onProgress({units}){tapPhase=units<0?'waiting':'recording';$('#tapStatus').textContent=units<0?'Noch nicht klopfen: erst die Klicks mitzählen.':'Jetzt selbst nachklopfen!';},onComplete(){tapPhase='done';const result=gradeTaps(onsetTimes(tapPattern,tapMeter,seconds),tapTimes,seconds,tapRelaxed);$('#tapResult').textContent=`${result.matched} von ${result.total} Tonanfängen getroffen. ${result.missed} fehlen; ${result.extra} zusätzliche Klopfer. `+(result.missed||result.extra?'Höre das Beispiel noch einmal und übe langsamer.':'Gut getroffen! Probiere einen neuen Rhythmus.');$('#tapStatus').textContent='Runde beendet. Du kannst noch einmal üben.';}});});on('tapPad',()=>{const p=$('#rhythmAudio');if(tapPhase!=='recording'||p.paused){$('#tapStatus').textContent='Tippe zuerst „Nachklopfen starten“ und warte die Anfangsklicks ab.';return;}const seconds=60/Number($('#tempo').value),time=p.currentTime-tapMeter*seconds;if(time<0||time>=tapMeter*seconds)return;tapTimes.push(time);const pad=$('#tapPad');pad.classList.add('playing');setTimeout(()=>pad.classList.remove('playing'),100);});}
